-- Dialy: Spanish and Portuguese food names. The app now also runs in
-- Spanish and Portuguese; this adds 'es' and 'pt' to the translations in
-- `names` (translated from the English names, Spain Spanish and European
-- Portuguese; source data-sources/food-names-es-pt.tsv, built into
-- src/data/foodNames/{es,pt}.json by scripts/import-food-names.mjs).
-- Same names as the Dialy-Editor transfers: without the Open Food Facts brand
-- in brackets (0016) and without "ecológico" / "biológico" (0042,
-- scripts/lib/organic.mjs).
--
-- 25909 foods in 9 parts (0043-0051, small enough for the SQL
-- Editor; run them in order, each one on its own). This is part 2 of 9.
-- Only missing languages are added: a name already in
-- `names` (e.g. edited in the Dialy-Editor) stays. Foods not in the
-- database are skipped. The foods_touch_updated_at trigger (0010) bumps
-- updated_at, so the app picks the names up on its next sync.

update public.foods f
set names = jsonb_build_object('es', v.es, 'pt', v.pt) || coalesce(f.names, '{}'::jsonb)
from (values
  ('bls-N410300', 'Café (infusión) con leche 3,5 % de grasa y azúcar', 'Café (infusão) com leite 3,5 % de gordura e açúcar'),
